class CustomStack:

    def __init__(self, maxSize: int):
        self.maxSize = maxSize
        self.stack = []
        self.add = []

    def push(self, x: int) -> None:
        if len(self.stack) < self.maxSize:
            self.stack.append(x)
            self.add.append(0)

    def pop(self) -> int:
        if not self.stack:
            return -1

        increment = self.add.pop()
        value = self.stack.pop() + increment

        if self.add:
            self.add[-1] += increment

        return value

    def increment(self, k: int, val: int) -> None:
        index = min(k, len(self.stack)) - 1
        if index >= 0:
            self.add[index] += val
