class Solution:
    def findKDistantIndices(self, nums: List[int], key: int, k: int) -> List[int]:
        result = []
        next_index = 0

        for j, value in enumerate(nums):
            if value == key:
                left = max(next_index, j - k)
                right = min(len(nums) - 1, j + k)

                if left <= right:
                    result.extend(range(left, right + 1))
                    next_index = right + 1

        return result
