from collections import deque


class MKAverage:

    def __init__(self, m: int, k: int):
        self.m = m
        self.k = k
        self.limit = 100000
        self.stream = deque()
        self.count_tree = [0] * (self.limit + 1)
        self.sum_tree = [0] * (self.limit + 1)

    def _update(self, value: int, delta: int) -> None:
        index = value
        while index <= self.limit:
            self.count_tree[index] += delta
            self.sum_tree[index] += value * delta
            index += index & -index

    def _sum_smallest(self, amount: int) -> int:
        if amount == 0:
            return 0

        index = 0
        count = 0
        total = 0
        step = 1 << (self.limit.bit_length() - 1)

        while step:
            next_index = index + step
            if (
                next_index <= self.limit
                and count + self.count_tree[next_index] < amount
            ):
                index = next_index
                count += self.count_tree[next_index]
                total += self.sum_tree[next_index]
            step >>= 1

        value = index + 1
        return total + (amount - count) * value

    def addElement(self, num: int) -> None:
        self.stream.append(num)
        self._update(num, 1)

        if len(self.stream) > self.m:
            removed = self.stream.popleft()
            self._update(removed, -1)

    def calculateMKAverage(self) -> int:
        if len(self.stream) < self.m:
            return -1

        middle_sum = (
            self._sum_smallest(self.m - self.k)
            - self._sum_smallest(self.k)
        )
        return middle_sum // (self.m - 2 * self.k)
