    def maxCompatibilitySum(self, students: List[List[int]], mentors: List[List[int]]) -> int:
        m = len(students)
        scores = [
            [
                sum(a == b for a, b in zip(student, mentor))
                for mentor in mentors
            ]
            for student in students
