class Solution:
    def minDays(self, bloomDay: List[int], m: int, k: int) -> int:
        if m * k > len(bloomDay):
            return -1

        def can_make(day: int) -> bool:
            bouquets = 0
            adjacent = 0

            for bloom in bloomDay:
                if bloom <= day:
                    adjacent += 1
                    if adjacent == k:
                        bouquets += 1
                        adjacent = 0
                        if bouquets >= m:
                            return True
                else:
                    adjacent = 0

            return False

        left, right = min(bloomDay), max(bloomDay)

        while left < right:
            mid = left + (right - left) // 2
            if can_make(mid):
                right = mid
            else:
                left = mid + 1

        return left
