from typing import List
import sys

class Solution:
    def numOfWays(self, nums: List[int]) -> int:
        MOD = 10**9 + 7
        n = len(nums)
        sys.setrecursionlimit(max(2000, n + 10))

        factorial = [1] * (n + 1)
        for i in range(1, n + 1):
            factorial[i] = factorial[i - 1] * i % MOD

        inv_factorial = [1] * (n + 1)
        inv_factorial[n] = pow(factorial[n], MOD - 2, MOD)
        for i in range(n, 0, -1):
            inv_factorial[i - 1] = inv_factorial[i] * i % MOD

        def combination(total: int, chosen: int) -> int:
            return (
                factorial[total]
                * inv_factorial[chosen]
                % MOD
                * inv_factorial[total - chosen]
                % MOD
            )

        def count_orders(values: List[int]) -> int:
            if len(values) <= 2:
                return 1

            root = values[0]
            left = []
            right = []

            for value in values[1:]:
                if value < root:
                    left.append(value)
                else:
                    right.append(value)

            ways = combination(len(values) - 1, len(left))
            ways = ways * count_orders(left) % MOD
            ways = ways * count_orders(right) % MOD
            return ways

        return (count_orders(nums) - 1) % MOD
