class Solution:
    def removeInvalidParentheses(self, s: str) -> List[str]:
        result = []

        def remove(current: str, scan_start: int, remove_start: int, pair: tuple) -> None:
            balance = 0

            for i in range(scan_start, len(current)):
                if current[i] == pair[0]:
                    balance += 1
                elif current[i] == pair[1]:
                    balance -= 1

                if balance >= 0:
                    continue

                for j in range(remove_start, i + 1):
                    if (
                        current[j] == pair[1]
                        and (j == remove_start or current[j - 1] != pair[1])
                    ):
                        remove(current[:j] + current[j + 1:], i, j, pair)
                return

            reversed_current = current[::-1]

            if pair[0] == '(':
                remove(reversed_current, 0, 0, (')', '('))
            else:
                result.append(reversed_current)

        remove(s, 0, 0, ('(', ')'))
        return result
