    def isScramble(self, s1: str, s2: str) -> bool:
        from functools import lru_cache

        n = len(s1)
        prefix1 = [[0] * 26 for _ in range(n + 1)]
        prefix2 = [[0] * 26 for _ in range(n + 1)]

        for i in range(n):
            prefix1[i + 1] = prefix1[i][:]
            prefix2[i + 1] = prefix2[i][:]
            prefix1[i + 1][ord(s1[i]) - ord('a')] += 1
            prefix2[i + 1][ord(s2[i]) - ord('a')] += 1

        def same_counts(i: int, j: int, length: int) -> bool:
            for c in range(26):
                if (prefix1[i + length][c] - prefix1[i][c] !=
                        prefix2[j + length][c] - prefix2[j][c]):
                    return False
            return True

        @lru_cache(None)
        def solve(i: int, j: int, length: int) -> bool:
            if s1[i:i + length] == s2[j:j + length]:
                return True

            if not same_counts(i, j, length):
                return False

            for split in range(1, length):
                if (solve(i, j, split) and
                        solve(i + split, j + split, length - split)):
                    return True

                if (solve(i, j + length - split, split) and
                        solve(i + split, j, length - split)):
                    return True

            return False

        return solve(0, 0, n)
