from functools import lru_cache
from collections import Counter


class Solution:
    def minStickers(self, stickers: List[str], target: str) -> int:
        target_letters = set(target)
        counts = []

        for sticker in stickers:
            count = Counter(ch for ch in sticker if ch in target_letters)
            counts.append(tuple(count.get(chr(i + 97), 0) for i in range(26)))

        counts = list(set(counts))
        counts = [
            current
            for current in counts
            if not any(
                current != other
                and all(current[i] <= other[i] for i in range(26))
                for other in counts
            )
        ]

        candidates = [[] for _ in range(26)]
        for count in counts:
            for letter in range(26):
                if count[letter]:
                    candidates[letter].append(count)

        target_count = Counter(target)
        initial = tuple(target_count.get(chr(i + 97), 0) for i in range(26))

        for letter, needed in enumerate(initial):
            if needed and not candidates[letter]:
                return -1

        @lru_cache(None)
        def solve(remaining):
            if not any(remaining):
                return 0

            first = next(i for i, amount in enumerate(remaining) if amount)
            best = float("inf")

            for sticker in candidates[first]:
                next_remaining = tuple(
                    max(0, remaining[i] - sticker[i]) for i in range(26)
                )
                result = solve(next_remaining)
                if result != float("inf"):
                    best = min(best, result + 1)

            return best

        answer = solve(initial)
        return -1 if answer == float("inf") else answer
