from functools import lru_cache

class Solution:
    def earliestAndLatest(self, n: int, firstPlayer: int, secondPlayer: int) -> List[int]:
        @lru_cache(None)
        def solve(players: int, first: int, second: int):
            if first + second == players + 1:
                return 1, 1

            possibilities = {(0, 0)}

            def contribution(position: int):
                if position < first:
                    return 1, 0
                if position < second:
                    return 0, 1
                return 0, 0

            for left in range(1, players // 2 + 1):
                right = players + 1 - left

                if first in (left, right) or second in (left, right):
                    options = {(0, 0)}
                else:
                    options = {contribution(left), contribution(right)}

                possibilities = {
                    (before_first + add_first, between + add_between)
                    for before_first, between in possibilities
                    for add_first, add_between in options
                }

            if players % 2:
                middle = players // 2 + 1
                if middle != first and middle != second:
                    add_first, add_between = contribution(middle)
                    possibilities = {
                        (before_first + add_first, between + add_between)
                        for before_first, between in possibilities
                    }

            next_players = (players + 1) // 2
            earliest = float("inf")
            latest = 0

            for before_first, between in possibilities:
                next_first = before_first + 1
                next_second = before_first + between + 2
                child_earliest, child_latest = solve(
                    next_players, next_first, next_second
                )
                earliest = min(earliest, child_earliest + 1)
                latest = max(latest, child_latest + 1)

