from typing import List
from math import gcd


class Solution:
    def getCoprimes(self, nums: List[int], edges: List[List[int]]) -> List[int]:
        n = len(nums)
        graph = [[] for _ in range(n)]
        for u, v in edges:
            graph[u].append(v)
            graph[v].append(u)

        coprime_values = [[] for _ in range(51)]
        for value in range(1, 51):
            for candidate in range(1, 51):
                if gcd(value, candidate) == 1:
                    coprime_values[value].append(candidate)

        value_stacks = [[] for _ in range(51)]
        answer = [-1] * n
        stack = [(0, -1, 0, False)]

        while stack:
            node, parent, depth, exiting = stack.pop()
            value = nums[node]

            if exiting:
                value_stacks[value].pop()
                continue

            closest_node = -1
            closest_depth = -1

            for candidate in coprime_values[value]:
                if value_stacks[candidate]:
                    ancestor_depth, ancestor_node = value_stacks[candidate][-1]
                    if ancestor_depth > closest_depth:
                        closest_depth = ancestor_depth
                        closest_node = ancestor_node

            answer[node] = closest_node
            value_stacks[value].append((depth, node))

            stack.append((node, parent, depth, True))
            for neighbor in graph[node]:
                if neighbor != parent:
                    stack.append((neighbor, node, depth + 1, False))

        return answer
